input.command:
cd /tmp/eff-jvfef9z4/work/kibana-api; H="Authorization: ApiKey $KIBANA_TEST_API_KEY"
DV='{"type":"data_view_reference","ref_id":"d3d7af60-4c81-11e8-b3d7-01146121b73d"}'
cat > $TMPDIR/d.json 2>/dev/null || true
cat > /tmp/d.json <<EOF
{"title":"S4-3ec7c5f2 Flights","panels":[
{"type":"vis","grid":{"x":0,"y":0,"w":24,"h":15},"config":{"type":"xy","title":"Flights over time","layers":[{"type":"line","data_source":$DV,"x":{"operation":"date_histogram","field":"timestamp"},"y":[{"operation":"count"}]}]}},
{"type":"vis","grid":{"x":24,"y":0,"w":24,"h":15},"config":{"type":"xy","title":"Flights per carrier","layers":[{"type":"bar","data_source":$DV,"x":{"operation":"terms","fields":["Carrier"],"limit":10},"y":[{"operation":"count"}]}]}}
]}
EOF
curl -s -X POST -H "$H" -H "kbn-xsrf: true" -H "Content-Type: application/json" "$KIBANA_URL/api/dashboards" -d @/tmp/d.json | head -c 3000

